class Solution {
  public long countNoZeroPairs(long n) {
    String s = Long.toString(n);
    int L = s.length();
    // state: carry (0/1), a finished, b finished
    long[][][] dp = new long[2][2][2];
    dp[0][0][0] = 1;
    for (int i = 0; i < L; i++) {
      int digit = s.charAt(L - 1 - i) - '0';
      long[][][] nd = new long[2][2][2];
      for (int carry = 0; carry < 2; carry++) {
        for (int fa = 0; fa < 2; fa++) {
          for (int fb = 0; fb < 2; fb++) {
            long v = dp[carry][fa][fb];
            if (v == 0) continue;
            for (int ca = 0; ca < 2; ca++) {
              // ca == 1: a is finished from this position on (digit 0), only allowed after position
              // 0
              if (fa == 1 && ca == 0) continue;
              if (ca == 1 && fa == 0 && i == 0) continue;
              int loA = ca == 1 ? 0 : 1, hiA = ca == 1 ? 0 : 9;
              for (int cb = 0; cb < 2; cb++) {
                if (fb == 1 && cb == 0) continue;
                if (cb == 1 && fb == 0 && i == 0) continue;
                int loB = cb == 1 ? 0 : 1, hiB = cb == 1 ? 0 : 9;
                for (int da = loA; da <= hiA; da++) {
                  for (int db = loB; db <= hiB; db++) {
                    int sum = da + db + carry;
                    if (sum % 10 != digit) continue;
                    nd[sum / 10][ca][cb] += v;
                  }
                }
              }
            }
          }
        }
      }
      dp = nd;
    }
    long total = 0;
    for (int fa = 0; fa < 2; fa++) for (int fb = 0; fb < 2; fb++) total += dp[0][fa][fb];
    return total;
  }
}
